// ===== Normalize Lead Message =====
// Reads the Meta envelope or a plain JSON post, and builds the idempotency key that
// Claim Event uses to make repeat deliveries harmless.
const c = $('Check Config').first().json;
const S = (v) => (v == null ? '' : String(v));
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  const value = body.entry?.[0]?.changes?.[0]?.value || body;
  const message = value.messages?.[0] || {};
  const contact = value.contacts?.[0] || {};
  const text = S(message.text?.body || body.text || body.message || body.message_text).trim();
  const from = S(message.from || body.from || body.customer_phone || body.whatsapp).replace(/\D/g, '');
  const name = S(contact.profile?.name || body.customer_name || body.name);
  // Meta sends delivery and read callbacks that carry no message. Emit a marker so the
  // run still reaches a Respond node instead of leaving Meta to retry.
  if (!from || !text) { out.push({ json: { skip: true, reason: 'not_a_customer_message' } }); continue; }
  const businessId = S(body.business_id || c.business_id) || 'default';
  const waMessageId = S(message.id || body.message_id) || ('manual-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8));
  const key = businessId + ':' + waMessageId;
  out.push({ json: {
    business_id: businessId,
    business_name: S(c.business_name),
    channel: 'whatsapp',
    customer_phone: from,
    customer_name: name,
    message_text: text.slice(0, 2000),
    phone_number_id: S(c.phone_number_id),
    owner_phone: S(c.owner_phone),
    wa_message_id: waMessageId,
    event_key: key,
    idempotency_key: key,
    received_at: new Date().toISOString()
  }});
}
return out;

// ===== Parse Lead Decision =====
// The model's reply is sent straight to a customer, so it is checked before it leaves.
// The prompt tells it never to quote prices; this enforces that rather than trusting it.
const c = $('Check Config').first().json;
const out = [];
for (const item of $input.all()) {
  const base = $('Normalize Lead Message').item.json;
  const raw = item.json || {};
  const flags = [];
  let ai = {};
  // AI Classify continues on failure, so an error item can arrive here. That must still
  // produce a polite reply and a handoff, never a dead end.
  if (raw.error || !raw.choices) { flags.push('AI_UNAVAILABLE'); }
  else {
    try { ai = JSON.parse(raw.choices?.[0]?.message?.content || '{}'); }
    catch (e) { flags.push('AI_OUTPUT_UNREADABLE'); }
  }

  const score = Number.isFinite(Number(ai.lead_score)) ? Math.max(0, Math.min(100, Number(ai.lead_score))) : 40;
  let human = ai.human_required === true || ai.next_action === 'handoff' || flags.length > 0;
  let reply = String(ai.reply || '').replace(/\*\*|__|`/g, '').trim();

  if (!reply) {
    flags.push('EMPTY_REPLY');
    reply = 'Thanks for your message. Someone from ' + (c.business_name || 'our team') + ' will get back to you shortly.';
    human = true;
  }
  const PRICE = /(?:\brs\.?|\bpkr\b|\busd\b|\$|\u00a3|\u20ac)\s?\d|\d[\d,]{2,}\s?(?:rs\b|pkr\b|rupees|dollars)|\b\d{1,3}\s?%\s?(?:off|discount)/i;
  if (c.allow_ai_pricing !== true && PRICE.test(reply)) {
    flags.push('PRICE_BLOCKED');
    reply = 'Thanks for your interest. I will get you exact pricing from the team - someone will confirm shortly.';
    human = true;
  }
  if (reply.length > 900) { reply = reply.slice(0, 897).trim() + '...'; flags.push('REPLY_TRUNCATED'); }

  out.push({ json: {
    ...base,
    intent: ai.intent || 'unknown',
    requested_service: ai.requested_service || null,
    urgency: ai.urgency || 'medium',
    budget: ai.budget || null,
    preferred_date: ai.preferred_date || null,
    preferred_time: ai.preferred_time || null,
    lead_score: score,
    temperature: score >= 75 ? 'hot' : score >= 45 ? 'warm' : 'cold',
    human_required: human,
    route: human ? 'handoff' : (ai.next_action || 'ask_question'),
    reply,
    guard_flags: flags.join('|'),
    ai_reason: ai.reason || '',
    processed_at: new Date().toISOString()
  }});
}
return out;

// ===== Check Config =====
// Everything a client must set lives in Config. If something is missing this stops here
// with a readable list, instead of failing three nodes later with a Meta or Supabase error.
const c = $json;
const body = c.body || {};
const S = (v) => (v == null ? '' : String(v));
const unset = (v) => !S(v).trim() || /^(YOUR_|PASTE_|CHANGE_ME|<)/i.test(S(v).trim());
const problems = [];
const phone_number_id = S(body.phone_number_id || c.phone_number_id);
const owner_phone = S(body.owner_phone || c.owner_phone).replace(/\D/g, '');
if (unset(phone_number_id)) problems.push('phone_number_id: paste the WhatsApp Cloud API phone number ID into the Config node');
if (!/^[1-9]\d{7,14}$/.test(owner_phone)) problems.push('owner_phone: international digits, no plus sign, e.g. 923001234567');
else if (/^92300000000\d$/.test(owner_phone)) problems.push('owner_phone: this is still the sample number, set the real owner WhatsApp number');
if (unset(c.owner_template_name)) problems.push('owner_template_name: the approved Meta template used for handoff alerts');
if (unset(c.business_name)) problems.push('business_name: shown to customers in fallback replies');
if (unset(c.ai_model)) problems.push('ai_model: e.g. gpt-4o-mini');
return [{ json: { ...c, phone_number_id, owner_phone, config_ok: problems.length === 0, problems } }];
